      "a.faqMarkup": "Markup é o que você soma ao seu custo. Margem é a parte do preço que fica com você. Se um cookie custa {one} e você vende por {two}, o markup é de 100%, mas a margem é de 50%. Minha aba Preço trabalha com margem.",
      "a.faqHowto": "Some quatro coisas de uma fornada: ingredientes, embalagem, seu tempo e custos fixos, como a luz. Divida pelas unidades que dá para vender e você tem o custo real por unidade. Depois some a margem que você quer ganhar. Me diga sua fornada e eu faço as contas.",
      "a.faqDeposit": "Em pedidos grandes ou personalizados, peça um sinal antes de comprar os ingredientes. Uma regra simples: o sinal cobre pelo menos ingredientes e embalagem, e o resto é pago na retirada. Coloque suas regras de sinal e cancelamento por escrito e envie com cada pedido.",
      "a.faqTime": "Defina um valor por hora para você, como pagaria a um ajudante. Escolha um valor que você aceitaria por um trabalho parecido onde mora e conte cada minuto: misturar, assar, esfriar, decorar, embalar e lavar a louça. Eu somo isso ao preço como minutos por fornada vezes seu valor, dividido pelas unidades.",
      "a.faqCottage": "As regras para vender comida feita em casa mudam de um lugar para outro. Elas podem tratar do que você pode vender, rótulos, licenças e onde vender. Confira as regras da sua região com o órgão local de vigilância sanitária. Não posso dar orientação jurídica.",
