      "a.greet": "Bonjour, je suis Bento\u00a0! Je chiffre vos pâtisseries, je calcule le coût de votre recette, je l’ajuste et je convertis les tasses en grammes. Essayez une de ces idées ou posez votre question.",
      "a.thanks": "Avec plaisir\u00a0! Bonne pâtisserie.",
      "a.help": "Je calcule un prix à la pièce ou à la boîte, le coût de votre recette, son ajustement, et je convertis tasses et cuillères en grammes. J’explique aussi la marge, les acomptes et comment facturer votre temps. Essayez une de ces idées\u00a0:",
      "a.cancel": "D’accord, on recommence. Que voulez-vous calculer\u00a0?",
      "a.unknown": "Pardon, je ne sais pas répondre à ça. Je calcule les prix à la pièce et à la boîte, le coût de votre recette, les ajustements de recette et les tasses ou cuillères en grammes. Essayez une de ces idées\u00a0:",
      "a.needNumber": "Il me faut un nombre pour ça. {q}",
      "a.askPcs": "{how} donne une fournée\u00a0?",
      "a.askIng": "Combien coûtent les ingrédients d’une fournée\u00a0? Par exemple, {ex}.",
      "a.askBox": "Combien de pièces vont dans la boîte\u00a0?",
      "a.askMargin": "Cette marge est trop élevée. Choisissez-en une entre 0 et 94\u00a0%. Quelle marge voulez-vous\u00a0?",
