      "a.uAsk": "Quel ingrédient\u00a0? Une tasse de farine et une tasse de sucre n’ont pas du tout le même poids.",
      "a.uUnknown": "Je n’ai pas de poids typique pour «\u00a0{name}\u00a0» dans mon tableau. Le poids d’une tasse ou d’une cuillère change beaucoup d’un ingrédient à l’autre\u00a0: pesez-le une fois et notez les grammes.",
      "a.uUnknownPiece": "Je n’ai pas de poids typique pour «\u00a0{name}\u00a0». Le poids d’une tasse ou d’une cuillère change beaucoup d’un ingrédient à l’autre\u00a0: pesez-le une fois et notez les grammes.",
      "a.uOk": "{name}\u00a0: {amt} ≈ {g}.",
      "a.uOk_s": "{name}\u00a0: {amt}, c’est environ {g}.",
