      "a.uTypical": "Valeur typique ({basis}). Pesez pour un résultat toujours identique.",
      "a.uTypicalCup": "Valeur typique. Pesez pour un résultat toujours identique.",
      "a.uTypical_s": "C’est une valeur typique, alors pesez si vous pouvez.",
      "a.uCupNote": "Je prends la tasse américaine, d’environ 240 ml.",
      "a.uCupNote_s": "Je prends la tasse américaine, d’environ 240 millilitres.",
      "a.uGlassNote": "Je prends un verre de {ml} ml (une tasse américaine fait environ 240 ml).",
      "a.uGlassNote_s": "Je prends un verre de {ml} millilitres.",
      "a.faqMarkup": "La majoration, c’est ce que vous ajoutez à votre coût. La marge, c’est la part du prix que vous gardez. Si un biscuit vous coûte {one} et que vous le vendez {two}, la majoration est de 100\u00a0%, mais la marge est de 50\u00a0%. Mon onglet Prix travaille avec la marge.",
      "a.faqHowto": "Additionnez quatre choses pour une fournée\u00a0: ingrédients, emballage, votre temps et frais généraux comme l’électricité. Divisez par le nombre de pièces vendables pour obtenir votre coût réel par pièce. Ajoutez ensuite la marge que vous voulez garder. Décrivez-moi votre fournée et je fais le calcul.",
      "a.faqDeposit": "Pour les grosses commandes ou les commandes sur mesure, demandez un acompte avant d’acheter les ingrédients. Règle simple\u00a0: un acompte qui couvre au moins les ingrédients et l’emballage, le reste étant payé au retrait. Mettez vos conditions d’acompte et d’annulation par écrit et envoyez-les avec chaque commande.",
      "a.faqTime": "Payez-vous un tarif horaire, comme vous paieriez un aide. Choisissez un tarif que vous accepteriez pour un travail similaire là où vous vivez, puis comptez chaque minute\u00a0: mélanger, cuire, refroidir, décorer, emballer et faire la vaisselle. Je l’ajoute au prix\u00a0: minutes par fournée fois votre tarif, divisé par le nombre de pièces.",
      "a.faqCottage": "Les règles pour vendre ce que vous préparez chez vous changent d’un endroit à l’autre. Elles peuvent porter sur ce que vous pouvez vendre, l’étiquetage, les autorisations et les lieux de vente. Vérifiez les règles locales auprès du service de sécurité alimentaire de votre région. Je ne peux pas donner de conseil juridique.",
      "a.pro": "De la photo à la recette et les commandes avec comptabilité arrivent bientôt dans Bento Pro. Inscrivez-vous gratuitement sur la liste d’attente et vous recevrez un e-mail quand ce sera prêt.",
      "act.price": "Ouvrir dans Prix",
      "act.recipe": "Ouvrir Recette",
      "act.scale": "Ouvrir dans Ajuster",
      "act.pro": "M’inscrire à Bento Pro",

