      "tip.0": "Pesez la farine au lieu d’utiliser des tasses. C’est le moyen le plus simple d’avoir le même biscuit à chaque fois.",
      "tip.1": "Comptez l’emballage. Boîtes, sachets et autocollants s’additionnent plus vite qu’on ne le pense.",
      "tip.2": "Chronométrez une fournée entière une fois, du mélange à la vaisselle. C’est ce temps-là qu’il faut facturer.",
      "tip.3": "Laissez les biscuits refroidir quelques minutes sur la plaque avant de les déplacer. Ils cassent moins.",
      "tip.4": "Demandez un acompte pour les grosses commandes avant d’acheter les ingrédients.",
      "tip.5": "Revoyez vos prix régulièrement. Le prix des ingrédients change, et le vôtre doit suivre.",
      "tip.6": "Sortez le beurre et les œufs à l’avance. Les ingrédients à température ambiante se mélangent mieux.",
      "tip.7": "Prévoyez quelques pièces invendables, cassées ou goûtées. C’est à ça que sert le pourcentage de perte.",
      "tip.8": "Étiquetez chaque boîte avec son contenu, la date et les allergènes.",
      "tip.9": "Faites une fournée d’essai avant une grosse commande et chronométrez-la. Vous fixerez le prix avec de vrais chiffres."
