      "a.uAsk": "Welche Zutat? Eine Tasse Mehl und eine Tasse Zucker wiegen ganz unterschiedlich.",
      "a.uUnknown": "Für „{name}“ habe ich kein typisches Gewicht in meiner Tabelle. Tassen- und Löffelgewichte sind von Zutat zu Zutat sehr verschieden, also wieg es einmal ab und notier dir die Gramm.",
      "a.uUnknownPiece": "Für „{name}“ habe ich kein typisches Gewicht. Tassen- und Löffelgewichte sind von Zutat zu Zutat sehr verschieden, also wieg es einmal ab und notier dir die Gramm.",
