      "a.uCupNote": "Ich rechne mit einer US-Tasse, etwa 240 ml.",
      "a.uCupNote_s": "Ich rechne mit einer amerikanischen Tasse, etwa 240 Milliliter.",
      "a.uGlassNote": "Ich rechne mit einem Glas von {ml} ml (eine US-Tasse hat etwa 240 ml).",
      "a.uGlassNote_s": "Ich rechne mit einem Glas von {ml} Millilitern.",
      "a.faqMarkup": "Der Aufschlag ist das, was du auf deine Kosten draufschlägst. Die Marge ist der Teil des Preises, den du behältst. Kostet ein Keks {one} und du verkaufst ihn für {two}, ist der Aufschlag 100 %, die Marge aber 50 %. Mein Preis-Tab rechnet mit der Marge.",
      "a.faqHowto": "Rechne für ein Rezept vier Dinge zusammen: Zutaten, Verpackung, deine Zeit und Nebenkosten wie Strom. Teile durch die Stückzahl, die du verkaufen kannst, dann hast du deine echten Kosten pro Stück. Danach kommt die Marge drauf, die du behalten willst. Nenn mir dein Rezept, und ich rechne.",
      "a.faqDeposit": "Verlang bei großen oder individuellen Bestellungen eine Anzahlung, bevor du die Zutaten kaufst. Eine einfache Regel: Die Anzahlung deckt mindestens Zutaten und Verpackung, der Rest wird bei Abholung bezahlt. Halte deine Bedingungen für Anzahlung und Stornierung schriftlich fest und schick sie bei jeder Bestellung mit.",
      "a.faqTime": "Zahl dir einen Stundenlohn, so wie du eine Aushilfe bezahlen würdest. Wähle einen Satz, den du für ähnliche Arbeit bei dir vor Ort annehmen würdest, und zähl jede Minute: rühren, backen, abkühlen, verzieren, verpacken und abwaschen. Ich rechne das in den Preis ein: Minuten pro Rezept mal Stundenlohn, geteilt durch die Stückzahl.",
      "a.faqCottage": "Die Regeln für den Verkauf von zu Hause Gebackenem sind von Ort zu Ort verschieden. Sie können festlegen, was du verkaufen darfst, wie du kennzeichnest, welche Genehmigungen du brauchst und wo du verkaufen darfst. Bitte erkundige dich bei der zuständigen Lebensmittelüberwachung vor Ort. Rechtsberatung kann ich nicht geben.",
      "a.pro": "Vom Foto zum Rezept und Bestellungen mit Buchhaltung kommen bald in Bento Pro. Trag dich kostenlos in die Warteliste ein, dann bekommst du eine E-Mail, sobald es fertig ist.",
      "act.price": "Im Preis-Tab öffnen",
