      "tip.0": "Wieg dein Mehl, statt Tassen zu nehmen. So wird jeder Keks am einfachsten gleich.",
      "tip.1": "Rechne die Verpackung mit. Boxen, Tüten und Aufkleber summieren sich schneller, als du denkst.",
      "tip.2": "Stopp einmal die Zeit für ein ganzes Rezept, vom Rühren bis zum Abwasch. Genau diese Zeit solltest du berechnen.",
      "tip.3": "Lass Kekse ein paar Minuten auf dem Blech abkühlen, bevor du sie bewegst. Dann brechen sie seltener.",
      "tip.4": "Nimm bei großen Bestellungen eine Anzahlung, bevor du die Zutaten kaufst.",
      "tip.5": "Prüf deine Preise alle paar Monate. Zutatenpreise ändern sich, und dein Preis sollte mitgehen.",
      "tip.6": "Nimm Butter und Eier früh aus dem Kühlschrank. Zimmerwarme Zutaten lassen sich gleichmäßiger verrühren.",
      "tip.7": "Plane ein paar Stück ein, die du nicht verkaufen kannst, etwa zerbrochene und Probierstücke. Dafür ist der Verlust in Prozent da.",
      "tip.8": "Beschrifte jede Box mit Inhalt, Datum und Allergenen.",
      "tip.9": "Back vor einer großen Bestellung ein Testrezept und stopp die Zeit. Dann kalkulierst du mit echten Zahlen."
