      "a.welcome": "Cześć, tu Bento! Zapytaj mnie, ile brać, ile kosztuje Twój przepis, jak go przeskalować albo ile gramów mieści się w szklance.",
      "a.greet": "Cześć, tu Bento! Wycenię Twoje wypieki, policzę koszt przepisu, przeskaluję go i zamienię szklanki na gramy. Wybierz jedną z podpowiedzi albo po prostu zapytaj.",
      "a.thanks": "Proszę bardzo! Udanego pieczenia.",
      "a.help": "Umiem policzyć cenę za sztukę albo za pudełko, koszt przepisu, przeskalować przepis i zamienić szklanki, filiżanki lub łyżki na gramy. Wyjaśnię też marżę, zaliczki i to, jak liczyć swój czas. Wybierz jedną z podpowiedzi:",
      "a.cancel": "Dobrze, zacznijmy od nowa. Co chcesz policzyć?",
      "a.unknown": "Przepraszam, tego nie wiem. Umiem policzyć ceny za sztukę i za pudełko, koszt przepisu, skalowanie oraz szklanki, filiżanki lub łyżki na gramy. Wybierz jedną z podpowiedzi:",
