      "a.uUnknown": "Nie mam typowej wagi dla „{name}” w mojej tabeli. Waga szklanki czy łyżki bardzo się różni między składnikami, więc zważ go raz i zapisz gramy.",
      "a.uUnknownPiece": "Nie mam typowej wagi dla „{name}”. Waga szklanki czy łyżki bardzo się różni między składnikami, więc zważ go raz i zapisz gramy.",
