      "a.uTypicalCup": "Typowa wartość. Zważ, jeśli chcesz mieć zawsze taki sam wynik.",
      "a.uTypical_s": "To typowa wartość, więc jeśli możesz, zważ.",
      "a.uCupNote": "Filiżanka to tu amerykańska miarka, ok. 240 ml.",
      "a.uCupNote_s": "Filiżanka to tu amerykańska miarka, około 240 mililitrów.",
      "a.uGlassNote": "Przyjmuję szklankę {ml} ml (amerykańska filiżanka to ok. 240 ml).",
      "a.uGlassNote_s": "Przyjmuję szklankę o pojemności {ml} mililitrów.",
      "a.faqMarkup": "Narzut to to, co dodajesz do kosztu. Marża to część ceny, która zostaje u Ciebie. Jeśli ciastko kosztuje Cię {one}, a sprzedajesz je za {two}, narzut wynosi 100%, ale marża 50%. Moja karta Cena liczy marżę.",
      "a.faqHowto": "Zsumuj cztery rzeczy dla jednej partii: składniki, opakowanie, swój czas i koszty stałe, np. prąd. Podziel przez liczbę sztuk, które możesz sprzedać, a dostaniesz prawdziwy koszt sztuki. Potem dodaj marżę, którą chcesz zarobić. Opisz mi swoją partię, a policzę resztę.",
      "a.faqDeposit": "Przy dużych lub nietypowych zamówieniach weź zaliczkę, zanim kupisz składniki. Prosta zasada: zaliczka pokrywa co najmniej składniki i opakowanie, a reszta jest płatna przy odbiorze. Zapisz warunki zaliczki i rezygnacji i wysyłaj je z każdym zamówieniem.",
      "a.faqTime": "Wyznacz sobie stawkę godzinową, tak jak dla pomocnika. Wybierz stawkę, która byłaby dla Ciebie w porządku za podobną pracę w Twojej okolicy, i licz każdą minutę: mieszanie, pieczenie, studzenie, dekorowanie, pakowanie i zmywanie. Doliczam to do ceny jako minuty na partię razy stawka, podzielone przez liczbę sztuk.",
      "a.faqCottage": "Zasady sprzedaży jedzenia robionego w domu różnią się w zależności od miejsca. Mogą dotyczyć tego, co wolno sprzedawać, etykiet, pozwoleń i miejsc sprzedaży. Sprawdź lokalne przepisy w urzędzie zajmującym się bezpieczeństwem żywności w Twojej okolicy. Nie mogę udzielać porad prawnych.",
      "a.pro": "Ze zdjęcia do przepisu i zamówienia z księgowością pojawią się wkrótce w Bento Pro. Zapisz się na darmową listę oczekujących, a dostaniesz jednego maila, gdy będzie gotowe.",
