      "a.uCupNote": "Чашка тут — американська мірна чашка, близько 240 мл.",
      "a.uCupNote_s": "Чашка тут — американська мірна чашка, близько 240 мілілітрів.",
      "a.uGlassNote": "Рахую склянку на {ml} мл (американська чашка — близько 240 мл).",
      "a.uGlassNote_s": "Рахую склянку на {ml} мілілітрів.",
      "a.faqMarkup": "Націнка — це те, що ви додаєте до собівартості. Маржа — це частина ціни, яка лишається вам. Якщо печиво коштує вам {one}, а ви продаєте його за {two}, націнка становить 100%, а маржа — 50%. Моя вкладка «Ціна» рахує маржу.",
      "a.faqHowto": "Складіть чотири речі для однієї партії: інгредієнти, пакування, ваш час і накладні витрати, як-от електрику. Поділіть на кількість штук, які можна продати, і отримаєте справжню собівартість штуки. Потім додайте маржу, яку хочете мати. Опишіть свою партію, і я порахую.",
      "a.faqDeposit": "Для великих чи індивідуальних замовлень беріть передоплату, перш ніж купувати інгредієнти. Просте правило: передоплата покриває щонайменше інгредієнти й пакування, а решту платять під час видачі. Запишіть умови передоплати і скасування та надсилайте їх із кожним замовленням.",
      "a.faqTime": "Платіть собі погодинну ставку, як платили б помічникові. Виберіть ставку, яку ви прийняли б за схожу роботу там, де живете, і рахуйте кожну хвилину: замішування, випікання, охолодження, декор, пакування і миття посуду. Я додаю це до ціни як хвилини на партію, помножені на ставку і поділені на кількість штук.",
      "a.faqCottage": "Правила продажу їжі, приготованої вдома, різняться залежно від місця. Вони можуть стосуватися того, що можна продавати, етикеток, дозволів і місць продажу. Перевірте місцеві правила у вашій службі з безпечності харчових продуктів. Я не можу давати юридичних порад.",
      "a.pro": "Від фото до рецепта і замовлення з обліком незабаром з’являться в Bento Pro. Запишіться до безкоштовного списку очікування, і ви отримаєте один лист, коли все буде готово.",
