      "say.pro": "Я учусь новым трюкам: из фото в рецепт и заказы с предоплатой. Хотите попробовать раньше других?",

      "a.welcome": "Привет, я Bento! Спросите, сколько брать, сколько стоит ваш рецепт, как его масштабировать или сколько граммов в стакане.",
      "a.greet": "Привет, я Bento! Я посчитаю цену вашей выпечки, себестоимость рецепта, масштабирую его и переведу стаканы в граммы. Выберите подсказку или просто спросите.",
      "a.thanks": "Пожалуйста! Удачной выпечки.",
      "a.help": "Я считаю цену за штуку или за коробку, себестоимость рецепта, масштабирую рецепт и перевожу стаканы, чашки или ложки в граммы. Ещё объясню маржу, предоплату и как считать своё время. Выберите подсказку:",
      "a.cancel": "Хорошо, начнём сначала. Что хотите посчитать?",
      "a.unknown": "Извините, этого я не знаю. Я считаю цены за штуку и за коробку, себестоимость рецепта, масштабирование и стаканы, чашки или ложки в граммы. Выберите подсказку:",
