      "a.uUnknown": "Для «{name}» в моей таблице нет типичного веса. Вес чашки или ложки сильно зависит от ингредиента, так что взвесьте один раз и запишите граммы.",
      "a.uUnknownPiece": "Для «{name}» нет типичного веса. Вес чашки или ложки сильно зависит от ингредиента, так что взвесьте один раз и запишите граммы.",
