      "a.faqMarkup": "Наценка — это то, что вы добавляете к себестоимости. Маржа — это часть цены, которая остаётся вам. Если печенье стоит вам {one}, а вы продаёте его за {two}, наценка 100 %, а маржа 50 %. Моя вкладка «Цена» считает маржу.",
      "a.faqHowto": "Сложите четыре вещи для одной партии: ингредиенты, упаковку, ваше время и накладные расходы, например электричество. Разделите на количество штук, которые можно продать, и получите настоящую себестоимость штуки. Потом добавьте маржу, которую хотите оставить себе. Опишите свою партию, и я посчитаю.",
      "a.faqDeposit": "Для больших или индивидуальных заказов берите предоплату до покупки ингредиентов. Простое правило: предоплата покрывает как минимум ингредиенты и упаковку, а остальное оплачивается при выдаче. Запишите условия предоплаты и отмены и отправляйте их с каждым заказом.",
      "a.faqTime": "Платите себе почасовую ставку, как платили бы помощнику. Выберите ставку, на которую вы согласились бы за похожую работу там, где живёте, и считайте каждую минуту: замес, выпечку, остывание, декор, упаковку и мытьё посуды. Я добавляю это в цену как минуты на партию, умноженные на ставку и делённые на количество штук.",
      "a.faqCottage": "Правила продажи еды, приготовленной дома, отличаются от места к месту. Они могут касаться того, что можно продавать, маркировки, разрешений и мест продажи. Проверьте местные правила в службе по безопасности пищевых продуктов вашего региона. Я не могу давать юридических советов.",
      "a.pro": "Из фото в рецепт и заказы с учётом скоро появятся в Bento Pro. Запишитесь в бесплатный лист ожидания, и вы получите одно письмо, когда всё будет готово.",
