      "tip.0": "Взвешивайте муку вместо того, чтобы мерить чашками. Так проще всего каждый раз получать одинаковое печенье.",
      "tip.1": "Считайте упаковку. Коробки, пакеты и наклейки набегают быстрее, чем кажется.",
      "tip.2": "Один раз засеките время целой партии, от замеса до мытья посуды. Именно за это время и стоит брать деньги.",
      "tip.3": "Дайте печенью остыть несколько минут на противне, прежде чем перекладывать. Так оно меньше ломается.",
      "tip.4": "Берите предоплату за большие заказы до покупки ингредиентов.",
      "tip.5": "Пересматривайте цены раз в несколько месяцев. Цены на ингредиенты меняются, и ваша цена должна за ними успевать.",
      "tip.6": "Достаньте масло и яйца заранее. Ингредиенты комнатной температуры смешиваются ровнее.",
      "tip.7": "Заложите несколько штук, которые не продадите: сломанные и на пробу. Для этого и нужен процент потерь.",
      "tip.8": "Подписывайте каждую коробку: что внутри, дата и аллергены.",
      "tip.9": "Перед большим заказом испеките пробную партию и засеките время. Тогда цена будет из реальных чисел."
